    26	
    27	impl NestedLoopJoiner {
    28	    /// Creates a new nested loop joiner.
    29	    pub fn new(
    30	        left: Rows,
    31	        right: Rows,
    32	        right_columns: usize,
    33	        predicate: Option<Expression>,
    34	        outer: bool,
