    47	    // Returns the next joined row, if any.
    48	    fn try_next(&mut self) -> Result<Option<Row>> {
    49	        loop {
    50	            if let Some(Ok(left_row)) = self.left.peek() {
    51	                if let Some(Ok(right_row)) = self.right.peek() {
    52	                    // Check if the predicate matches
    53	                    let matches = if let Some(ref pred) = self.predicate {
    54	                        let mut combined_row = left_row.clone();
    55	                        combined_row.extend(right_row.iter().cloned());
    56	                        pred.evaluate(Some(&combined_row))
    57	                            .map(|v| v == Value::Boolean(true))
    58	                            .unwrap_or(false)
    59	                    } else {
    60	                        true
    61	                    };
    62	
    63	                    if matches {
